@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
  + number : int
}

class Discount {
  + amount : int
}

class Visitor {
  + name : string
}

class Guide {
  + name : string
}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "1" -- "1" Guide
GuidedTour "0..20" -- "*" Visitor
Visitor "1" -- "*" Discount
Discount "*" -- "1" GuidedTour

@enduml

